transform-configuration-object-into-depl:
%dw 2.0
output application/json
---
payload mapObject (value, key) ->
  do {
    var snakeKey = upper((key as String) replace /([a-z0-9])([A-Z])/ with ((m) -> m[1] ++ "_" ++ m[2]))
    ---
    { (snakeKey): if (value is String) '"' ++ value ++ '"' else value }
  }
